<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('registration.php');$page_title='Pendaftaran & Antrean';$page_subtitle=is_role('registration')?'Front office: patient registration, MPI/MRN, guarantor, dan queue management.':'Clinical queue view; tenaga klinis tidak mengubah data administratif pasien.';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';
 if($action==='register'&&is_role('registration')){$mrn='MRN-'.str_pad((string)((int)$pdo->query('SELECT COALESCE(MAX(id),0)+1 FROM patients')->fetchColumn()),6,'0',STR_PAD_LEFT);$q=$pdo->prepare('INSERT INTO patients(mrn,name,nik,gender,birth_date,blood_type,phone,address,emergency_contact,emergency_phone,insurance) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$mrn,trim($_POST['name']),trim($_POST['nik']),$_POST['gender'],$_POST['birth_date'],trim($_POST['blood_type']),trim($_POST['phone']),trim($_POST['address']),trim($_POST['emergency_contact']),trim($_POST['emergency_phone']),trim($_POST['insurance'])]);$pid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO registrations(patient_id,registered_by,visit_type,guarantor,complaint,status) VALUES(?,?,?,?,?,?)');$q->execute([$pid,current_user_id(),$_POST['visit_type'],trim($_POST['insurance'])?:'Umum',trim($_POST['complaint']),'registered']);audit($pdo,'CREATE','REGISTRATION',$pid,'Episode kunjungan dan MRN dibuat oleh petugas pendaftaran.');$msg='Registrasi berhasil. MRN: '.$mrn;}
 elseif($action==='status'&&(is_role('registration')||is_role('nurse'))){$id=(int)$_POST['id'];$status=$_POST['status']??'';$allowed=is_role('nurse')?['triaged','queued']:['registered','queued','completed','cancelled'];if(!in_array($status,$allowed,true)){$msg='Transisi status tidak sesuai kewenangan role.';}else{$s=$pdo->prepare('UPDATE registrations SET status=? WHERE id=?');$s->execute([$status,$id]);audit($pdo,'UPDATE','REGISTRATION',$id,'Status episode menjadi '.$status);$msg='Status episode diperbarui.';}}
}
$rows=$pdo->query("SELECT r.*,p.name,p.mrn,p.phone FROM registrations r JOIN patients p ON p.id=r.patient_id ORDER BY r.registration_date DESC")->fetchAll();include __DIR__.'/includes/header.php';?>
<?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')||str_contains($msg,'diperbarui')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?>
<?php if(is_role('registration')):?><div class="card"><div class="card-header"><div><h3 class="section-title">Patient Registration</h3><p class="section-subtitle">Buat satu MRN dan satu episode kunjungan untuk setiap registrasi.</p></div><span class="tag">Front Office</span></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="register"><div class="form-grid"><div><label>Nama</label><input name="name" required></div><div><label>NIK</label><input name="nik" required></div><div><label>Gender</label><select name="gender"><option value="male">Laki-laki</option><option value="female">Perempuan</option></select></div><div><label>Tanggal Lahir</label><input type="date" name="birth_date" required></div><div><label>Gol. Darah</label><input name="blood_type" placeholder="O+"></div><div><label>Telepon</label><input name="phone"></div><div><label>Penjamin</label><input name="insurance" placeholder="BPJS / Asuransi / Umum"></div><div><label>Jenis Kunjungan</label><select name="visit_type"><option value="outpatient">Rawat Jalan</option><option value="inpatient">Rawat Inap</option><option value="emergency">IGD</option></select></div></div><br><label>Alamat</label><textarea name="address"></textarea><div class="form-grid"><div><label>Kontak Darurat</label><input name="emergency_contact"></div><div><label>Telepon Darurat</label><input name="emergency_phone"></div></div><br><label>Keluhan Utama</label><textarea name="complaint" required></textarea><button class="btn primary" style="margin-top:10px">+ Registrasikan</button></form></div><div style="height:18px"></div><?php endif;?>
<div class="card"><div class="card-header"><div><h3 class="section-title">Episode Queue</h3><p class="section-subtitle">registered → triaged → queued → completed / cancelled</p></div></div><div class="table-wrap"><table><tr><th>MRN</th><th>Pasien</th><th>Kunjungan</th><th>Penjamin</th><th>Keluhan</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['mrn'])?></td><td><b><?=h($r['name'])?></b><br><span class="mini"><?=h($r['phone'])?></span></td><td><?=h($r['visit_type'])?></td><td><?=h($r['guarantor'])?></td><td><?=h($r['complaint'])?></td><td><span class="badge <?=$r['status']==='completed'?'ok':($r['status']==='cancelled'?'danger':'warn')?>"><?=h(strtoupper($r['status']))?></span></td><td><?php if(is_role('registration')||is_role('nurse')):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach((is_role('nurse')?['triaged','queued']:['registered','queued','completed','cancelled']) as $st):?><option value="<?=$st?>" <?=$r['status']===$st?'selected':''?>><?=h($st)?></option><?php endforeach;?></select></form><?php else:?><span class="mini">Read-only clinical queue</span><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php include __DIR__.'/includes/footer.php';?>